"""Build a compact self-contained review package, excluding third-party papers."""
from pathlib import Path
import datetime,hashlib,json,shutil,zipfile

ROOT=Path(__file__).resolve().parents[1]
STAGE=ROOT.parents[1]/'work'/'fourth-power-review-bundle-stage'
STAGE.mkdir(parents=True,exist_ok=True)
files=['fourth-power-review-manuscript.md', 'collatz-fourth-power-growth-review.pdf', 'fourth-power-interpolation-bound.md', 'two-regime-interpolation-bound.md', 'cycle-bound-corollaries.md', 'block-restart-capacity.md', 'majorization-lemma.md', 'global-growth-and-cycle-bound.md', 'src/exact_intervals.py', 'src/audit_two_regime_bound.py', 'src/audit_fourth_power_bound.py', 'src/audit_cycle_bound_corollaries.py', 'src/audit_fourth_power_review_constants.py', 'results/two-regime-exponential-bound-audit.json', 'results/fourth-power-exponential-bound-audit.json', 'results/cycle-bound-corollaries-audit.json', 'results/fourth-power-review-constants-audit.json', 'results/fourth-power-review-pdf-qa.json', 'results/interpolation-primary-source-provenance.json']
files += [p.relative_to(ROOT).as_posix() for p in (ROOT/'formal').iterdir() if p.is_file()]
for name in files:
    dst=STAGE/name;dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(ROOT/name,dst)
shutil.copyfile(ROOT/'src/verify_fourth_power_bundle.py',STAGE/'verify_bundle.py')
readme="# Collatz block-growth research: strongest analytic review package\n\nPrepared for Luke Baer with Codex, 29 September 2026.\n\nStart with `collatz-fourth-power-growth-review.pdf` (seven pages). Its complete\nMarkdown source is included. This is a private candidate mathematical result;\nindependent review and priority verification remain pending. Collatz remains open.\n\nThe principal theorem bounds maximal odd-run lengths along every positive\norbit by A*y0*lambda^t, where t counts maximal odd/even blocks,\nlambda=log2(3)-1/93 (approximately 1.57420981255), B=32768, and\nA=(log2(3)/lambda)^28 (approximately 1.20998096465). It specializes Bugeaud's\n1999 p-adic interpolation theorem using fourth-power normalization in two\nranges and a dyadic tail, then combines local losses through bounded restarts.\nSince lambda>1, the bound permits unbounded trajectories.\n\nPublished cycle-size estimates give K<1.51*m*lambda^m for\n1024<=m<=515619 and K<15.17*m*lambda^m for m>=515620, where m counts local\nminima and K counts odd terms in a hypothetical nontrivial cycle. The latter\nuses an affine envelope and an explicit bootstrap from an already established\nweaker bound. These comparisons do not establish priority against later work.\n\n## What needs mathematical review\n\n1. Match every specialized hypothesis to Bugeaud (1999), Theorem 1, rational\n   clause (6). Check the sign, heights, congruences, and both cardinalities.\n2. Check the factorial normalization and both finite parameter choices for\n   every even J>=200; check the unbounded dyadic argument for all q>=9.\n3. Check the retained two-block loss and the restart induction, including the\n   intermediate run-length bound. Actual heights need not contract each block.\n4. Check the cycle conventions, published range table, and affine bootstrap.\n\nThe PDF supplies the full derivation. The frozen `fourth-power-interpolation-bound.md`\nand its earlier `two-regime-interpolation-bound.md` and `cycle-bound-corollaries.md`\ndependencies are preserved separately. Earlier constants in supporting notes\nand formal modules describe historical or generic results, not replacements\nfor the principal theorem. The formal aggregate includes all accepted support\nlemmas, including earlier variants.\n\n## Reproduce the checks\n\nPython 3.11 or newer is sufficient; no third-party package is required:\n\n    python verify_bundle.py\n    python verify_bundle.py --numeric\n\nThe first command checks every file hash and binds saved Lean receipts to\ntheir source files and compiler logs. The second reruns four exact/numerical\naudits in a temporary copy, requiring byte-for-byte agreement with the saved\nreceipts. It leaves this package unchanged and accesses no network.\n\nTo recompile all 85 supporting lemmas in 19 modules, obtain Lean 4.34.1 and\nmathlib commit d13f23b723b8a846827a245b89c10fc7d3f11612, initialize its\ndeclared dependencies/cache, and run:\n\n    python formal/verify_all_formal.py --mathlib PATH_TO_MATHLIB --lean-bin PATH_TO_LEAN_BIN\n\nThe Lake project builds four core modules; use the aggregate verifier for all\nnineteen. Only Lean's standard propext, Classical.choice and Quot.sound axioms\noccur. No external proof service or AI model is invoked by these checks.\n\nThe formal files prove supporting algebra, congruence, inequalities,\nmajorization and envelope lemmas. They do not formalize the published p-adic\ntheorem, its full Collatz specialization, or convergence. Finite numerical\nchallenges supplement the written universal proofs and cannot replace them.\n\n## Archive scope\n\nThis compact archive contains analytic proofs, exact checks, formal sources,\nreceipts and review material. The separate finite-search certificates are not\nincluded and are unnecessary for this analytic theorem. Third-party papers,\nLean binaries, mathlib and caches are not redistributed. Follow the primary\nlinks in the manuscript. The provenance record identifies privately inspected\nsource files; those files are intentionally absent. The SHA256 manifest detects\naccidental changes; it is not a digital signature or mathematical endorsement.\n"
(STAGE/'START-HERE.md').write_text(readme,encoding='utf-8')
included=files+['verify_bundle.py','START-HERE.md']
manifest={'format_version':1,'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
          'scope':'Analytic review bundle only; no finite-search certificate or proof of convergence.',
          'files':{name:{'bytes':(STAGE/name).stat().st_size,
                         'sha256':hashlib.sha256((STAGE/name).read_bytes()).hexdigest()}
                   for name in sorted(included)}}
(STAGE/'MANIFEST.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8')
archive=ROOT/'collatz-fourth-power-review-bundle.zip'
with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=9) as z:
    for name in sorted(included+['MANIFEST.json']):
        info=zipfile.ZipInfo(name,date_time=(2026,9,29,0,0,0));info.compress_type=zipfile.ZIP_DEFLATED
        z.writestr(info,(STAGE/name).read_bytes())
receipt={'archive':archive.name,'sha256':hashlib.sha256(archive.read_bytes()).hexdigest(),
         'bytes':archive.stat().st_size,'files':len(included)+1,
         'builder_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
         'manifest_sha256':hashlib.sha256((STAGE/'MANIFEST.json').read_bytes()).hexdigest(),
         'scope':manifest['scope']}
(ROOT/'results/fourth-power-review-bundle-build.json').write_text(json.dumps(receipt,indent=2)+'\n',encoding='utf-8')
print(json.dumps(receipt),flush=True)
